import { Component } from '@angular/core';
import { PiensoService } from 'src/app/services/pienso.service';
import { MisComprasService } from 'src/app/services/mis-compras.service';

@Component({
  selector: 'app-main',
  templateUrl: './main.component.html',
  styleUrls: ['./main.component.css']
})
export class MainComponent {
  public primerProd: string = "";
  public categoria: string = "";

  constructor(public piensoService: PiensoService, public misComprasService: MisComprasService){

    this.misComprasService.primerProd().subscribe{
      (res:any) =>{
        this.primerProd = res;
      }
    }

    setTimeout( () =>{
      this.piensoService.conseguirCategoria(this.primerProd).subscribe(
        (res:any)=>{
          this.categoria = res;
        }
      )
    },100)


    setTimeout( () =>{
      this.piensoService.conseguirPiensosCategoria
    },200);

  }
}
<!--PRODUCTOS-->
<div class="row">
    <div class="col-md-2">
            <app-latizq></app-latizq>
    </div>
    <div class="col-md-7">
        <!--ejercicio 55-->
        <div style="background-color:hotpink">
            
        </div>


        <!--ejercicio 17-->
        <app-epadre17></app-epadre17><br>

        <!--ejercicio 16-->
        <app-epadre16></app-epadre16>

        <div class="row">
            <!--PANEL MIS COMPRAS-->
            <app-mis-compras></app-mis-compras>
            <!--PANEL ADMIN-->
            <app-panel-admin></app-panel-admin>
            <div *ngFor="let pienso of piensoService.piensos" class="col-md-4" style="margin-bottom: 3%">
              <app-producto [piensoEnviado]="pienso"></app-producto>
            </div>
        </div>

    </div>
    <div class="col-md-3">
        <app-latder></app-latder>
    </div>
</div>
